/*
 * A025638  Exponent of 2 (value of i) in n-th number of form 2^i*9^j.
 * https://oeis.org/A025638
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = exponent of 2 in n-th number of the form 2^i * 9^j
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by a standard Hamming‑type merge of the two
 * multipliers 2 and 9.  An array of previously generated terms is kept
 * (exponent of 2, exponent of 3/2 and a long‑double logarithm for
 * comparison).  The algorithm is O(n) and works for any n ≥ 1. */

#include <stdlib.h>
#include <stdint.h>
#include <math.h>

seq_t a(idx_t n)
{
    if (n <= 0) return (seq_t)0;           /* undefined for n==0, but safe */

    /* static state */
    static seq_t *e2  = NULL;           /* exponent of 2 for each term   */
    static uint32_t *e3 = NULL;          /* exponent of 3 (not 9) for each term  */
    static long double *logv = NULL;      /* log₂(2^i 9^j) = i + 2 j log₂(3)  */
    static idx_t sz = 0;                 /* number of terms generated      */
    static size_t cap = 0;               /* allocated capacity             */
    static idx_t p2 = 0, p9 = 0;         /* pointers for next candidates  */

    const long double LOG2_3 = log2l(3.0L);
    const long double LOG2_9 = 2.0L * LOG2_3;

    /* initialise storage */
    if (sz == 0) {
        cap = 16;
        e2   = (seq_t*)       malloc(cap * sizeof(seq_t));
        e3   = (uint32_t*)    malloc(cap * sizeof(uint32_t));
        logv = (long double*)malloc(cap * sizeof(long double));

        e2[0] = (seq_t)0;      /* 2⁰·9⁰ = 1  */
        e3[0] = 0;             /* exponent of 3 in 9⁰ is 0   */
        logv[0] = 0.0L;        /* log₂(1) = 0                */
        sz = 1;
        p2 = 0; p9 = 0;
    }

    /* generate terms until we have at least n terms */
    while (sz < n) {
        /* candidate produced by multiplying e2[p2] with 2 */
        idx_t cand2_i = (idx_t)(e2[p2] + 1);
        uint32_t cand2_j = e3[p2];
        long double cand2_log = logv[p2] + 1.0L;     /* log₂(2) = 1 */

        /* candidate produced by multiplying e2[p9] with 9 (i.e. 3²) */
        idx_t cand9_i = (idx_t)e2[p9];
        uint32_t cand9_j = e3[p9] + 1;
        long double cand9_log = logv[p9] + LOG2_9;

        idx_t next_i;
        uint32_t next_j;

        /* decide which candidate is smaller (lexicographic order is
         * preserved by using long double logs with a tiny epsilon).  */
        if (cand2_log < cand9_log - 1e-12L) {
            /* only candidate from multiplying by 2 */
            next_i = cand2_i;  next_j = cand2_j;
            p2++;
        } else if (cand2_log > cand9_log + 1e-12L) {
            /* only candidate from multiplying by 9 */
            next_i = cand9_i;  next_j = cand9_j;
            p9++;
        } else {
            /* candidates are numerically equal; check exponents
             * to detect the duplicate case exactly. */
            if (cand2_i == cand9_i && cand2_j == cand9_j) {
                /* duplicate produced by two different paths:
                 * advance both pointers. */
                p2++; p9++;
            } else {
                /* very unlikely floating‑point tie, but still
                 * advance both to avoid endless loop. */
                p2++; p9++;
            }
            next_i = cand2_i; next_j = cand2_j;   /* either works */
        }

        /* store the new term */
        if (sz == cap) {
            cap = cap ? cap * 2 : 16;
            e2   = (seq_t*)       realloc(e2,   cap * sizeof(seq_t));
            e3   = (uint32_t*)    realloc(e3,   cap * sizeof(uint32_t));
            logv = (long double*)realloc(logv, cap * sizeof(long double));
        }
        e2[sz]   = (seq_t)next_i;
        e3[sz]   = next_j;
        logv[sz] = (long double)next_i + 2.0L * (long double)next_j * LOG2_3;
        sz++;
    }

    return e2[n - 1];
}
